<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { supabase } from '@/lib/supabase'
type Definition={id:string;setting_key:string;label:string;description:string|null;input_type:string;options:string[];default_value:unknown;required:boolean;enabled:boolean;sort_order:number}
const rows=ref<Definition[]>([]),loading=ref(false),saving=ref(false),error=ref(''),search=ref(''),show=ref(false),editing=ref<Definition|null>(null)
const key=ref(''),label=ref(''),description=ref(''),inputType=ref('text'),options=ref(''),defaultValue=ref(''),required=ref(false),enabled=ref(true),sortOrder=ref(0)
const filtered=computed(()=>{const q=search.value.trim().toLowerCase();return q?rows.value.filter(r=>[r.setting_key,r.label,r.description??''].some(v=>v.toLowerCase().includes(q))):rows.value})
function openForm(row?:Definition){editing.value=row??null;key.value=row?.setting_key??'';label.value=row?.label??'';description.value=row?.description??'';inputType.value=row?.input_type??'text';options.value=row?.options?.join(', ')??'';defaultValue.value=row?.default_value==null?'':String(row.default_value);required.value=row?.required??false;enabled.value=row?.enabled??true;sortOrder.value=row?.sort_order??0;error.value='';show.value=true}
function close(){show.value=false;editing.value=null}
async function load(){loading.value=true;error.value='';try{const {data,error:e}=await supabase.from('system_setting_definitions').select('*').order('sort_order').order('label');if(e)throw e;rows.value=(data??[]).map((d:any)=>({...d,options:Array.isArray(d.options)?d.options.map(String):[]})) as Definition[]}catch(e:any){error.value=e.message??'Unable to load setting definitions'}finally{loading.value=false}}
async function save(){saving.value=true;error.value='';try{if(!key.value.trim()||!label.value.trim())throw new Error('Enter both a setting code and a name.');let def:unknown=defaultValue.value;if(inputType.value==='number'&&defaultValue.value!=='')def=Number(defaultValue.value);if(inputType.value==='boolean')def=defaultValue.value==='true';const payload={setting_key:key.value.trim().toLowerCase().replace(/[^a-z0-9_]+/g,'_'),label:label.value.trim(),description:description.value.trim()||null,input_type:inputType.value,options:inputType.value==='select'?options.value.split(',').map(x=>x.trim()).filter(Boolean):[],default_value:defaultValue.value===''?null:def,required:required.value,enabled:enabled.value,sort_order:Number(sortOrder.value),updated_at:new Date().toISOString()};const result=editing.value?await supabase.from('system_setting_definitions').update(payload).eq('id',editing.value.id):await supabase.from('system_setting_definitions').insert(payload);if(result.error)throw result.error;close();await load()}catch(e:any){error.value=e.message??'Unable to save setting'}finally{saving.value=false}}
async function remove(row:Definition){if(!confirm('Delete “'+row.label+'”? Shop values saved for this setting will also be deleted.'))return;const {error:e}=await supabase.from('system_setting_definitions').delete().eq('id',row.id);if(e)error.value=e.message;else await load()}
onMounted(load)
</script>
<template><section class="space-y-6">
 <header class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-semibold uppercase tracking-wide text-indigo-600">SYSTEM CONTROL</p><h1 class="mt-1 text-3xl font-bold">Shop setting options</h1><p class="mt-2 text-sm text-slate-500">Create the settings Shop Directors can configure. Use clear names and simple instructions.</p></div><button class="btn btn-primary" @click="openForm()">＋ Add setting option</button></header>
 <p v-if="error" class="rounded-lg bg-red-50 p-3 text-sm text-red-700">{{error}}</p>
 <div class="panel overflow-hidden"><div class="flex flex-wrap items-center gap-3 border-b p-4"><input v-model="search" class="field max-w-sm" placeholder="Search setting options"><button class="btn btn-muted" @click="load">Refresh</button><span class="text-xs text-slate-500">{{filtered.length}} options</span></div><div v-if="loading" class="p-8 text-center text-slate-500">Loading…</div><div v-else class="overflow-x-auto"><table class="table w-full"><thead><tr><th>Setting</th><th>What it controls</th><th>Input type</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td><b>{{r.label}}</b><small class="block text-slate-400">{{r.setting_key}}</small></td><td>{{r.description||'—'}}</td><td class="capitalize">{{r.input_type}}</td><td>{{r.enabled?'Available':'Hidden'}}</td><td><div class="flex gap-3"><button class="text-indigo-700" @click="openForm(r)">Edit</button><button class="text-red-600" @click="remove(r)">Delete</button></div></td></tr><tr v-if="!filtered.length"><td colspan="5" class="p-6 text-center text-slate-500">No setting options created yet.</td></tr></tbody></table></div></div>
 <div v-if="show" class="modal-mask"><form class="modal-card max-h-[90vh] space-y-4 overflow-y-auto" @submit.prevent="save"><div class="flex items-center justify-between"><h2 class="text-xl font-bold">{{editing?'Edit setting option':'Create setting option'}}</h2><button type="button" class="text-slate-500" @click="close">Close</button></div>
 <label class="block text-sm font-medium">Setting code<input v-model="key" class="field mt-1" required maxlength="80" :disabled="!!editing" placeholder="e.g. allow_credit_sales"></label>
 <label class="block text-sm font-medium">Name shown to Shop Director<input v-model="label" class="field mt-1" required placeholder="e.g. Allow credit sales"></label>
 <label class="block text-sm font-medium">Simple explanation<textarea v-model="description" class="field mt-1" rows="2" placeholder="Explain what this option does in everyday language."></textarea></label>
 <label class="block text-sm font-medium">How should the Director answer?<select v-model="inputType" class="field mt-1"><option value="text">Short text</option><option value="textarea">Long text</option><option value="number">Number</option><option value="boolean">On / Off switch</option><option value="email">Email address</option><option value="phone">Phone number</option><option value="url">Website address</option><option value="select">Choose from a list</option></select></label>
 <label v-if="inputType==='select'" class="block text-sm font-medium">Available choices (separate with commas)<input v-model="options" class="field mt-1" placeholder="Cash, Mobile Money, Bank"></label>
 <label class="block text-sm font-medium">Default value<input v-model="defaultValue" class="field mt-1" :type="inputType==='number'?'number':'text'" placeholder="Optional"></label>
 <label class="flex items-center gap-2 text-sm"><input v-model="required" type="checkbox"> The Director must fill this in</label><label class="flex items-center gap-2 text-sm"><input v-model="enabled" type="checkbox"> Make this option available to shops</label>
 <label class="block text-sm font-medium">Display order<input v-model.number="sortOrder" type="number" class="field mt-1"></label>
 <p v-if="error" class="text-sm text-red-600">{{error}}</p><div class="flex justify-end gap-2"><button type="button" class="btn btn-muted" @click="close">Cancel</button><button class="btn btn-primary" :disabled="saving">{{saving?'Saving…':'Save option'}}</button></div></form></div>
</section></template>